CREATE TABLE IF NOT EXISTS integrations (id INTEGER PRIMARY KEY, platform TEXT NOT NULL, shop_region TEXT, access_token TEXT, refresh_token TEXT, expires_at INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shops (id TEXT PRIMARY KEY, name TEXT, region TEXT, raw_json TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT, status TEXT, started_at TEXT DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS daily_shop_metrics (shop_id TEXT, metric_date TEXT, orders INTEGER DEFAULT 0, products INTEGER DEFAULT 0, inventory INTEGER DEFAULT 0, gross_revenue REAL DEFAULT 0, commission REAL DEFAULT 0, returns INTEGER DEFAULT 0, PRIMARY KEY(shop_id,metric_date));
